import numpy as np


def _median3(x):
    x = np.asarray(x, dtype=float)
    if x.size < 3:
        return x.copy()
    z = np.empty_like(x)
    z[0] = x[0]
    z[-1] = x[-1]
    z[1:-1] = np.median(np.stack((x[:-2], x[1:-1], x[2:]), axis=0), axis=0)
    return z


def _reflect_convolve(x, kernel):
    r = len(kernel) // 2
    if r == 0:
        return x.copy()
    xp = np.pad(x, (r, r), mode="reflect")
    return np.convolve(xp, kernel, mode="valid")


def _gaussian(sigma, radius):
    t = np.arange(-radius, radius + 1, dtype=float)
    k = np.exp(-0.5 * (t / sigma) ** 2)
    return k / np.sum(k)


def adaptive_filter(x, window_size=20):
    x = np.asarray(x, dtype=float)
    if len(x) < window_size:
        raise ValueError("input shorter than window")
    return np.convolve(x, np.ones(window_size) / window_size, mode="valid")


def enhanced_filter_with_trend_preservation(x, window_size=20):
    """Apply robust zero-phase Butterworth smoothing with median spike rejection and Savitzky-Golay trend blending."""
    x = np.asarray(x, dtype=float).copy()
    if len(x) < window_size:
        raise ValueError("input shorter than window")

    if not np.all(np.isfinite(x)):
        good = np.isfinite(x)
        if not np.any(good):
            x[:] = 0.0
        else:
            idx = np.arange(len(x))
            x = np.interp(idx, idx[good], x[good])

    n = len(x)
    if n == 0:
        return np.empty(0, dtype=float)

    d = np.diff(x)
    if d.size:
        dm = float(np.median(d))
        scale = 1.4826 * float(np.median(np.abs(d - dm))) / np.sqrt(2.0)
    else:
        scale = 0.0
    scale = max(scale, 1e-4)
    spread = max(float(np.std(x)), scale)
    cutoff = float(np.clip(
        0.10 / (1.0 + 1.5 * scale / (spread + 1e-8)), 0.045, 0.16))

    try:
        from scipy.signal import butter, sosfiltfilt, savgol_filter
        order = 2 if n < 80 else 4
        if n < 80:
            cutoff = max(cutoff, 0.08)
        sos = butter(order, cutoff, btype="low", output="sos")
        padlen = min(n - 1, max(3, 3 * (2 * len(sos) + 1)))
        if n > padlen + 2:
            estimate = sosfiltfilt(sos, x, padlen=padlen)
        else:
            estimate = _reflect_convolve(x, np.ones(3, dtype=float) / 3.0)

        residual = x - estimate
        if float(np.median(np.abs(residual))) > 2.5 * scale:
            cleaned = _median3(x)
            if n > padlen + 2:
                estimate = sosfiltfilt(sos, cleaned, padlen=padlen)
            else:
                estimate = _reflect_convolve(
                    cleaned, np.ones(3, dtype=float) / 3.0)

        largest = min(15, window_size if window_size % 2 else window_size - 1)
        if largest >= 3:
            trend = savgol_filter(
                x, largest, 2, mode="interp" if n > largest else "nearest")
            estimate = 0.75 * estimate + 0.25 * trend
    except (ImportError, ValueError):
        radius = max(1, min(4, window_size // 4))
        kernel = np.ones(2 * radius + 1, dtype=float)
        kernel /= kernel.sum()
        estimate = _reflect_convolve(_median3(x), kernel)

    return np.asarray(estimate[window_size - 1:], dtype=float)


def process_signal(input_signal, window_size=20, algorithm_type="enhanced"):
    if algorithm_type == "enhanced":
        return enhanced_filter_with_trend_preservation(input_signal, window_size)
    return adaptive_filter(input_signal, window_size)


def generate_test_signal(length=1000, noise_level=0.3, seed=42):
    rng = np.random.RandomState(seed)
    t = np.linspace(0, 10, length)
    clean_signal = (
        2 * np.sin(2 * np.pi * 0.5 * t)
        + 1.5 * np.sin(2 * np.pi * 2 * t)
        + 0.5 * np.sin(2 * np.pi * 5 * t)
        + 0.8 * np.exp(-t / 5) * np.sin(2 * np.pi * 1.5 * t)
    )
    clean_signal += 0.1 * t * np.sin(0.2 * t)
    clean_signal += np.cumsum(rng.randn(length) * 0.05)
    return clean_signal + rng.normal(0, noise_level, length), clean_signal


def run_signal_processing(noisy_signal=None, signal_length=1000,
                          noise_level=0.3, window_size=20):
    if noisy_signal is None:
        noisy_signal, clean_signal = generate_test_signal(
            signal_length, noise_level)
    else:
        noisy_signal = np.asarray(noisy_signal, dtype=float)
        clean_signal = None

    filtered = process_signal(noisy_signal, window_size, "enhanced")
    result = {
        "filtered_signal": filtered,
        "clean_signal": None,
        "noisy_signal": None,
        "correlation": 0,
        "noise_reduction": 0,
        "signal_length": len(filtered),
    }

    if clean_signal is not None:
        clean = clean_signal[window_size - 1:]
        noisy = noisy_signal[window_size - 1:]
        m = min(len(filtered), len(clean))
        filtered = filtered[:m]
        clean = clean[:m]
        noisy = noisy[:m]
        corr = np.corrcoef(filtered, clean)[0, 1] if m > 1 else 0.0
        before = np.var(noisy - clean)
        after = np.var(filtered - clean)
        result.update({
            "filtered_signal": filtered,
            "clean_signal": clean,
            "noisy_signal": noisy,
            "correlation": float(corr),
            "noise_reduction": float((before - after) / before)
                if before > 0 else 0.0,
            "signal_length": m,
        })
    return result


if __name__ == "__main__":
    r = run_signal_processing()
    print("Signal processing completed!")
    print(f"Correlation with clean signal: {r['correlation']:.3f}")
    print(f"Noise reduction: {r['noise_reduction']:.3f}")
    print(f"Processed signal length: {r['signal_length']}")
